if(a>b) cout<<"a is greater";

if(a>b) cout<<"a"; else cout<<"b";

உள் if (Nested if) — பல நிபந்தனைகளை வரிசையாகச் சரிபார்க்க.

switch(grade) { case 'A': cout<<"Excellent"; break; default: cout<<"Average"; }

for(i=1;i<=5;i++) cout<<i;

while(i<=5){ cout<<i; i++; }

do{ cout<<i; i++; } while(i<=5);

மூன்றும் 1-5 எண்களைக் காட்டும்; for தொடக்கம்/நிபந்தனை/அதிகரிப்பு ஒரே வரியில், while நிபந்தனையை முன்பே சரிபார்க்கும், do-while தொகுதியை ஒரு முறையாவது இயக்கும்.

for(i=1;i<=10;i++){
  for(j=1;j<=10;j++){
    cout<<i*j<<"\\t";
  }
  cout<<endl;
}

வெளிப்புற loop வரிசைகளையும், உள்புற loop நெடுவரிசைகளையும் கட்டுப்படுத்தி, 10×10 பெருக்கல் அட்டவணையை உருவாக்கும்.

break எடுத்துக்காட்டு:
for(i=1;i<=10;i++){ if(i==5) break; cout<<i; }
// 1 2 3 4

continue எடுத்துக்காட்டு:
for(i=1;i<=5;i++){ if(i==3) continue; cout<<i; }
// 1 2 4 5

goto எடுத்துக்காட்டு:
if(error) goto end;
...
end: cout<<"Program ended";
